export const DEFAULT_LEGEND_RATIO = 25;

const LEGEND_RATIO_RANGE: { min: number; max: number } = {
  min: 5,
  max: 80,
};

/**
 * Returns the value of the ratio if it is in the range of allowed values (5-80), otherwise it will return the default ratio
 * @param legendRatio
 */
export const sanitizeLegendRatio = (legendRatio: number): number =>
  legendRatio < LEGEND_RATIO_RANGE.min || legendRatio > LEGEND_RATIO_RANGE.max
    ? DEFAULT_LEGEND_RATIO
    : legendRatio;
